Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='stewriting', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='Write comments, docs, commits and reports in plain Simplified Technical English', body='Use short sentences, at most 20 words for an instruction and 25 for a description. Use the active voice, one topic per sentence, and one word for one thing. Name a concrete subject, a plain verb and an explicit object, and define each term of art once. Use no idiom, no slogan and no data that acts like a person. Keep the articles.', rationale='Compressed or figurative prose must be decoded, and plain prose is read the same way by people, agents and translators.', supersedes=()))